package com.pocketstock.app;
import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.Color;import android.net.Uri;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.*;import java.nio.charset.*;import java.util.*;import java.util.concurrent.*;

public class MainActivity extends Activity {
 SQLiteDatabase db;ArrayList<String> headers=new ArrayList<>();ArrayList<Item> shown=new ArrayList<>();ListView list;TextView count;EditText search;int titleCol=0;String undoValues;long undoId;boolean busy=false;ExecutorService worker=Executors.newSingleThreadExecutor();
 static class Item{long id;ArrayList<String> values;Item(long i,ArrayList<String> v){id=i;values=v;}}
 int dp(int n){return (int)(n*getResources().getDisplayMetrics().density);}
 TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(Color.rgb(24,55,46));return t;}
 LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(16),dp(8),dp(16),dp(8));return l;}
 Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setMinHeight(dp(48));b.setOnClickListener(v->{if(!busy)r.run();});return b;}
 @Override public void onCreate(Bundle state){super.onCreate(state);db=openOrCreateDatabase("stock.db",MODE_PRIVATE,null);db.execSQL("CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY,value TEXT)");db.execSQL("CREATE TABLE IF NOT EXISTS products (_id INTEGER PRIMARY KEY AUTOINCREMENT, fields TEXT NOT NULL)");loadHeaders();LinearLayout root=column();root.setBackgroundColor(Color.rgb(243,245,240));root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(16),dp(8)+i.getSystemWindowInsetTop(),dp(16),dp(8)+i.getSystemWindowInsetBottom());return i;});root.addView(text("Pocket Stock",28));root.addView(text("Offline shop database • saved on this phone",13));LinearLayout bar=new LinearLayout(this);bar.addView(button("Import CSV",this::importPicker),new LinearLayout.LayoutParams(0,-2,1));bar.addView(button("Export CSV",this::exportPicker),new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);search=new EditText(this);search.setSingleLine(true);search.setHint("Search name, code, barcode…");root.addView(search);LinearLayout actions=new LinearLayout(this);actions.addView(button("＋ Add item",()->edit(null)),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button("Name field",this::chooseTitle),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button("Undo",this::undo),new LinearLayout.LayoutParams(0,-2,1));root.addView(actions);count=text("",13);root.addView(count);list=new ListView(this);list.setDividerHeight(dp(8));root.addView(list,new LinearLayout.LayoutParams(-1,0,1));list.setOnItemClickListener((p,v,pos,id)->{if(!busy)edit(shown.get(pos));});setContentView(root);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int c){refresh();}public void afterTextChanged(Editable e){}});refresh();}
 void loadHeaders(){headers.clear();try(Cursor c=db.rawQuery("SELECT value FROM meta WHERE key='headers'",null)){if(c.moveToFirst())headers=values(c.getString(0));}titleCol=getPreferences(0).getInt("title",0);if(titleCol>=headers.size())titleCol=0;}
 ArrayList<String> values(String s){ArrayList<String> out=new ArrayList<>();try{JSONArray a=new JSONArray(s);for(int i=0;i<a.length();i++)out.add(a.optString(i,""));}catch(Exception e){throw new IllegalStateException("Invalid stored data",e);}return out;}
 void error(Exception e){new AlertDialog.Builder(this).setTitle("Could not complete action").setMessage(e.getMessage()).setPositiveButton("OK",null).show();}
 void say(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void refresh(){if(busy)return;shown.clear();String q=search.getText().toString().trim().toLowerCase(Locale.ROOT);String[] terms=q.split("\\s+");try(Cursor c=db.rawQuery("SELECT _id,fields FROM products ORDER BY _id DESC",null)){while(c.moveToNext()){Item item=new Item(c.getLong(0),values(c.getString(1)));String all=String.join(" ",item.values).toLowerCase(Locale.ROOT);boolean match=true;for(String t:terms)if(!all.contains(t)){match=false;break;}if(match)shown.add(item);}}count.setText(shown.size()+" products"+(headers.isEmpty()?" • Import a CSV or add your first item":" • Tap a product to edit"));list.setAdapter(new BaseAdapter(){public int getCount(){return shown.size();}public Object getItem(int p){return shown.get(p);}public long getItemId(int p){return shown.get(p).id;}public View getView(int p,View old,ViewGroup parent){Item item=shown.get(p);LinearLayout card=column();card.setBackgroundColor(Color.WHITE);TextView title=text(item.values.size()>titleCol?item.values.get(titleCol):"Product",19);title.setTypeface(null,1);card.addView(title);StringBuilder detail=new StringBuilder();for(int i=0;i<Math.min(headers.size(),item.values.size());i++)if(i!=titleCol&&!item.values.get(i).isEmpty()){if(detail.length()>0)detail.append("\n");detail.append(headers.get(i)).append(": ").append(item.values.get(i));}TextView sub=text(detail.toString(),14);sub.setMaxLines(4);card.addView(sub);return card;}});}
 void ensureHeaders(){if(!headers.isEmpty())return;headers.addAll(Arrays.asList("Stock Code","Description","Qty","Unit Cost","Sell Incl","Notes"));ContentValues v=new ContentValues();v.put("key","headers");v.put("value",new JSONArray(headers).toString());db.insertWithOnConflict("meta",null,v,SQLiteDatabase.CONFLICT_REPLACE);titleCol=1;getPreferences(0).edit().putInt("title",1).apply();}
 void edit(Item item){ensureHeaders();LinearLayout fields=column();ArrayList<EditText> inputs=new ArrayList<>();for(int i=0;i<headers.size();i++){fields.addView(text(headers.get(i),13));EditText input=new EditText(this);input.setText(item==null?"":item.values.get(i));input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE);fields.addView(input);inputs.add(input);}ScrollView scroll=new ScrollView(this);scroll.addView(fields);AlertDialog d=new AlertDialog.Builder(this).setTitle(item==null?"Add product":"Edit product").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).setNeutralButton(item==null?"":"Delete",null).create();d.setOnShowListener(shownDialog->{d.getButton(-1).setOnClickListener(v->{ArrayList<String> vals=new ArrayList<>();boolean any=false;for(EditText input:inputs){String s=input.getText().toString();vals.add(s);any|=!s.trim().isEmpty();}if(!any){say("Enter at least one field");return;}try{ContentValues cv=new ContentValues();cv.put("fields",new JSONArray(vals).toString());if(item==null){long id=db.insertOrThrow("products",null,cv);undoId=id;undoValues=null;}else{db.update("products",cv,"_id=?",new String[]{""+item.id});undoId=item.id;undoValues=new JSONArray(item.values).toString();}d.dismiss();refresh();say("Saved on this phone");}catch(Exception e){error(e);}});d.getButton(-3).setVisibility(item==null?View.GONE:View.VISIBLE);d.getButton(-3).setOnClickListener(v->new AlertDialog.Builder(this).setMessage("Delete this product? Undo is available until your next change or app restart.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(a,b)->{try{db.delete("products","_id=?",new String[]{""+item.id});undoId=item.id;undoValues=new JSONArray(item.values).toString();d.dismiss();refresh();}catch(Exception e){error(e);}}).show());});d.show();}
 void undo(){if(undoId==0){say("No item change to undo");return;}try{if(undoValues==null)db.delete("products","_id=?",new String[]{""+undoId});else{ContentValues cv=new ContentValues();cv.put("_id",undoId);cv.put("fields",undoValues);db.insertWithOnConflict("products",null,cv,SQLiteDatabase.CONFLICT_REPLACE);}undoId=0;undoValues=null;refresh();say("Change undone");}catch(Exception e){error(e);}}
 void chooseTitle(){if(headers.isEmpty()){say("Import a CSV first");return;}new AlertDialog.Builder(this).setTitle("Product name column").setSingleChoiceItems(headers.toArray(new String[0]),titleCol,(d,which)->{titleCol=which;getPreferences(0).edit().putInt("title",which).apply();d.dismiss();refresh();}).setNegativeButton("Cancel",null).show();}
 void importPicker(){startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),1);}
 void exportPicker(){if(headers.isEmpty()){say("Nothing to export yet");return;}startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("text/csv").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"PocketStock-updated.csv"),2);}
 interface Job{void run()throws Exception;}
 void background(String label,Job job,Runnable done){busy=true;count.setText(label);worker.execute(()->{try{job.run();runOnUiThread(()->{busy=false;done.run();refresh();});}catch(Exception e){runOnUiThread(()->{busy=false;refresh();error(e);});}});}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(req==1)background("Reading CSV…",()->{byte[] bytes;try(InputStream in=getContentResolver().openInputStream(uri);ByteArrayOutputStream out=new ByteArrayOutputStream()){if(in==null)throw new IOException("File unavailable");byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>25*1024*1024)throw new IOException("Please use a CSV under 25 MB");}bytes=out.toByteArray();}String s;try{s=StandardCharsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(bytes)).toString();}catch(CharacterCodingException e){s=new String(bytes,Charset.forName("windows-1252"));}List<List<String>> rows=Csv.detect(s);List<String> h=rows.remove(0);Set<String> names=new HashSet<>();for(int i=0;i<h.size();i++){h.set(i,h.get(i).trim());if(h.get(i).isEmpty()||!names.add(h.get(i)))throw new IOException("Headers must be unique and non-empty");}for(int i=0;i<rows.size();i++)if(rows.get(i).size()!=h.size())throw new IOException("Data row "+(i+1)+" has a different number of columns");runOnUiThread(()->confirmImport(h,rows));},()->{});else if(req==2)background("Exporting CSV…",()->{try(OutputStream stream=getContentResolver().openOutputStream(uri,"wt")){if(stream==null)throw new IOException("Cannot create export");Writer out=new OutputStreamWriter(stream,StandardCharsets.UTF_8);out.write('\uFEFF');out.write(Csv.line(headers));try(Cursor c=db.rawQuery("SELECT fields FROM products ORDER BY _id",null)){while(c.moveToNext())out.write(Csv.line(values(c.getString(0))));}out.flush();}},()->say("CSV exported"));}
 void confirmImport(List<String> h,List<List<String>> rows){new AlertDialog.Builder(this).setTitle("Import "+rows.size()+" products?").setMessage("Columns: "+String.join(", ",h)+"\n\nReplace deletes the current list. Export a backup first. Append keeps duplicate products. Your original CSV is unchanged.").setNegativeButton("Cancel",null).setPositiveButton("Replace",(d,w)->new AlertDialog.Builder(this).setMessage("Replace the entire current database? This import cannot be undone.").setNegativeButton("Cancel",null).setPositiveButton("Replace",(a,b)->doImport(h,rows,false)).show()).setNeutralButton(headers.equals(h)?"Append":null,(d,w)->doImport(h,rows,true)).show();}
 void doImport(List<String> h,List<List<String>> rows,boolean append){background("Saving imported products…",()->{db.beginTransaction();try{if(!append){db.delete("products",null,null);ContentValues m=new ContentValues();m.put("key","headers");m.put("value",new JSONArray(h).toString());db.insertWithOnConflict("meta",null,m,SQLiteDatabase.CONFLICT_REPLACE);}for(List<String> row:rows){ContentValues v=new ContentValues();v.put("fields",new JSONArray(row).toString());db.insertOrThrow("products",null,v);}db.setTransactionSuccessful();}finally{db.endTransaction();}},()->{undoId=0;if(!append){int best=0;for(int i=0;i<h.size();i++)if(h.get(i).toLowerCase(Locale.ROOT).matches(".*description.*|.*product.*name.*|name")){best=i;break;}getPreferences(0).edit().putInt("title",best).apply();}loadHeaders();search.setText("");say("Import complete");});}
}
